/* Multiverse Arena v0.9.7.7.2 — Stable Bootstrap + V1 release hardening */
(()=>{
'use strict';
const BUILD='0.9.7.7.2';
const IS_DEV=location.pathname.includes('/dev/');
const ASSET=IS_DEV?('dev-'+Date.now()):'09772';
const SAVE_KEY='fightArenaV08';
const CORE='app/core/core-runtime-v0958.js';
const MODULES=['app/config/runtime-manifest.js','app/config/feature-flags.js','app/state/state.js','app/input/input.js','app/characters/database.js','app/characters/validator.js','app/characters/characters.js','app/combat/invariants.js','app/combat/api.js','app/combat/combat.js','app/core/game.js','app/ui/ui.js','app/owner/storage.js','app/owner/commands.js','app/debug/error-logger.js','app/debug/debug-panel.js','app/save/migrations.js','app/systems/save.js','app/release/build-info.js','app/ui/ownerboard.js'];
const FALLBACK_RUNTIME=['device-v092.js','touch-v0941.js','stability-v0941.js','campaign-v097.js','ui-v09571.js','polish-v09572.js','premium-v096.js','update-v0962.js','update-v0963.js','update-v0964.js','update-v097.js','update-v0971.js','update-v0972.js','update-v0973.js','update-v0974.js','update-v09741.js','update-v0975.js','update-v09751.js','update-v0976.js','update-v09761.js','update-v0977.js','update-v09771.js','update-v09772.js','owner-devtools-v09772.js'];
const state={version:BUILD,asset:ASSET,saveKey:SAVE_KEY,coreArtifact:CORE,moduleFoundation:'0.9.7.7.7-dev',branch:IS_DEV?'dev':'main',modules:MODULES.slice(),status:'booting',loaded:[],failed:[],runtime:[]};window.MultiverseArenaRuntime=state;
const src=path=>`${path}?v=${encodeURIComponent(ASSET)}`;
function script(path){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src(path);s.async=false;s.dataset.coreBoot=BUILD;s.onload=()=>{state.loaded.push(path);resolve(path)};s.onerror=()=>{state.failed.push(path);window.MultiverseArenaModules?.errorLogger?.error?.('Script load failed',{path});reject(new Error('Failed to load '+path))};document.body.appendChild(s)})}
function waitFor(test,timeout,label){return new Promise((resolve,reject)=>{const started=Date.now();const check=()=>{let value=false;try{value=test()}catch{}if(value)return resolve(value);if(Date.now()-started>=timeout)return reject(new Error(label+' readiness timeout'));setTimeout(check,30)};check()})}
function brand(){document.title='Multiverse Arena v0.9.7.7.2';document.querySelectorAll('.brand .tag').forEach(x=>x.textContent=IS_DEV?'DEV v0.9.7.7.7':'v0.9.7.7.2');const h=document.querySelector('.build-health b');if(h)h.textContent=IS_DEV?'DEV • RELEASE HARDENING':'v0.9.7.7.2 • STABLE';const c=document.querySelector('#deviceChooser .eyebrow');if(c)c.textContent=IS_DEV?'MULTIVERSE ARENA • DEV':'MULTIVERSE ARENA • v0.9.7.7.2'}
function fatal(err){state.status='error';window.MultiverseArenaModules?.errorLogger?.error?.(err?.message||err,{stack:err?.stack||null,phase:'bootstrap'});console.error('[Multiverse Arena bootstrap]',err);const h=document.querySelector('.build-health b');if(h)h.textContent='DEV • CORE LOAD ERROR'}
function validateModules(){const m=window.MultiverseArenaModules;const missing=['runtimeManifest','features','state','input','characterDB','characterValidator','characters','combatInvariants','combatAPI','combat','game','ui','ownerStorage','ownerCommands','errorLogger','debug','saveMigrations','save','buildInfo','ownerboard'].filter(name=>!m?.[name]);if(missing.length){state.status='warning';state.moduleMissing=missing;m?.errorLogger?.warn?.('Missing modular core pieces',{missing});return false}state.moduleReady=true;return true}
function validateReady(){const m=window.MultiverseArenaModules,missing=[];if(window.FightArena?.version!=='0.9.5.7')missing.push('FightArena core');if(!window.FightArenaTrainingControls)missing.push('training');if(!window.FightArenaDailyControls)missing.push('daily');if(!window.FightArenaCampaignV097)missing.push('campaign');if(!window.MultiverseArenaUpdate09772)missing.push('runtime');if(!window.MultiverseArenaOwnerDevTools)missing.push('owner dev tools');validateModules();m?.characterDB?.refresh?.();const chars=m?.characterValidator?.validateAll?.();if(chars&&!chars.ok)m?.errorLogger?.warn?.('Character validation warning',{results:chars.results});if(missing.length){state.status='warning';state.missing=missing;m?.errorLogger?.warn?.('Runtime readiness warning',{missing})}else if(state.moduleReady)state.status='ready';setTimeout(()=>{brand();window.MultiverseArenaUpdate09772?.audit?.()},300)}window.addEventListener('fightarena-ready',validateReady,{once:true});
async function boot(){try{brand();await script(CORE);for(const f of MODULES)await script(f);window.MultiverseArenaModules?.characterDB?.refresh?.();if(window.FightArena?.version!=='0.9.5.7')throw new Error('canonical core version mismatch');const runtime=window.MultiverseArenaModules?.runtimeManifest?.ordered||FALLBACK_RUNTIME;state.runtime=runtime.slice();for(const f of runtime)await script(f);await waitFor(()=>window.MultiverseArenaUpdate09772&&window.MultiverseArenaOwnerDevTools&&window.MultiverseArenaModules?.saveMigrations&&window.MultiverseArenaModules?.characterValidator&&window.MultiverseArenaModules?.combatInvariants&&window.MultiverseArenaModules?.buildInfo&&window.MultiverseArenaModules?.ownerboard,5000,'dev runtime');window.MultiverseArenaModules?.characterDB?.refresh?.();window.dispatchEvent(new Event('fightarena-ready'));setTimeout(()=>{if(state.status==='booting')validateReady()},500)}catch(err){fatal(err)}}boot();
})();